"""Build a Word version of the manuscript from main_submit.tex (generated by make_submit.py).

Steps: resolve \\ref from main_submit.aux, turn \\cite into Nature-style superscript numbers in
bibliography order, rewrite the Springer Nature front matter as plain LaTeX, turn the
thebibliography into a numbered list, use PNG figures, then run pandoc to produce
main_submit.docx. Usage: python scripts/make_word.py
"""
import os
import re
import subprocess

HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
import sys
STEM = sys.argv[1] if len(sys.argv) > 1 else "main_submit"   # e.g. main_anon for the version without authors
SRC = os.path.join(HERE, STEM + ".tex")
AUX = os.path.join(HERE, STEM + ".aux")
TMP = os.path.join(HERE, "word_build")
OUT = os.path.join(HERE, STEM + ".docx")


def braced(s, i):
    """Return (content, end) of the {...} group starting at s[i] == '{'."""
    assert s[i] == "{", s[i:i + 30]
    d = 0
    for j in range(i, len(s)):
        if s[j] == "{":
            d += 1
        elif s[j] == "}":
            d -= 1
            if d == 0:
                return s[i + 1:j], j + 1
    raise ValueError("unbalanced")


def replace_cmd(s, name, fn, nargs=1):
    out, i = [], 0
    pat = "\\" + name
    while True:
        k = s.find(pat + "{", i)
        if k < 0:
            out.append(s[i:])
            return "".join(out)
        out.append(s[i:k])
        j = k + len(pat)
        args = []
        for _ in range(nargs):
            a, j = braced(s, j)
            args.append(a)
        out.append(fn(*args))
        i = j


def compress(nums):
    nums = sorted(set(nums))
    parts, a = [], 0
    while a < len(nums):
        b = a
        while b + 1 < len(nums) and nums[b + 1] == nums[b] + 1:
            b += 1
        if b - a >= 2:
            parts.append(f"{nums[a]}--{nums[b]}")
        else:
            parts.extend(str(n) for n in nums[a:b + 1])
        a = b + 1
    return ",".join(parts)


def main():
    s = open(SRC, encoding="utf-8").read()
    labels = dict(re.findall(r"\\newlabel\{([^}]*)\}\{\{([^}]*)\}", open(AUX, encoding="utf-8").read()))

    # body only
    s = s[s.index("\\begin{document}") + len("\\begin{document}"):s.index("\\end{document}")]

    s = replace_cmd(s, "TBD", lambda x: f"\\textbf{{[TBD: {x}]}}")
    s = s.replace("\\tfrac", "\\frac")

    # front matter
    title = re.search(r"\\title\[[^\]]*\]\{", s)
    t, _ = braced(s, title.end() - 1)
    authors = []
    for m in re.finditer(r"\\author\*?\[([^\]]*)\]\{\\fnm\{([^}]*)\} \\sur\{([^}]*)\}\}", s):
        star = "*" if s[m.start():m.start() + 8] == "\\author*" else ""
        authors.append(f"{m.group(2)} {m.group(3)}\\textsuperscript{{{m.group(1)}{star}}}")
    affils = []
    for m in re.finditer(r"\\affil\*?\[([^\]]*)\]\{", s):
        body, _ = braced(s, m.end() - 1)
        for c in ("orgaddress", "orgdiv", "orgname", "city", "state", "country"):
            body = replace_cmd(body, c, lambda x: x)
        affils.append(f"\\textsuperscript{{{m.group(1)}}}{body}")
    em = re.search(r"\\email\{([^}]*)\}", s)
    ab = s.index("\\abstract{")
    abstract, _ = braced(s, ab + len("\\abstract"))
    kw = s.index("\\keywords{")
    keywords, _ = braced(s, kw + len("\\keywords"))
    front = f"\\begin{{center}}\\textbf{{\\Large {t}}}\\end{{center}}\n\n"
    if authors:
        front += f"{', '.join(authors)}\n\n" + "\n\n".join(affils) + "\n\n"
    if em:
        front += f"*Corresponding author. E-mail: {em.group(1)}\n\n"
    front += f"\\section*{{Abstract}}\n{abstract}\n\n\\noindent\\textbf{{Keywords:}} {keywords}\n\n"
    s = front + s[s.index("\\maketitle") + len("\\maketitle"):]

    # bibliography -> numbered list, citation numbers
    b0, b1 = s.index("\\begin{thebibliography}"), s.index("\\end{thebibliography}") + len("\\end{thebibliography}")
    bib = s[b0:b1]
    items = re.split(r"\\bibitem\{([^}]*)\}", bib)[1:]
    keys = items[0::2]
    num = {k: i + 1 for i, k in enumerate(keys)}
    entries = []
    for k, body in zip(items[0::2], items[1::2]):
        body = body.replace("\\end{thebibliography}", "")
        body = re.sub(r"\\bibinfo\{[^}]*\}\{", "{", body)
        body = body.replace("\\newblock", " ").replace("\\BibitemOpen", "").replace("\\BibitemShut{NoStop}", "")
        body = re.sub(r"\\(urlprefix|doi|url)\b", "", body)
        body = re.sub(r"\s+", " ", body).strip()
        entries.append(f"\\item {body}")
    s = s[:b0] + "\\section*{References}\n\\begin{enumerate}\n" + "\n".join(entries) + "\n\\end{enumerate}\n" + s[b1:]

    def cite(keys_):
        ns = [num[k.strip()] for k in keys_.split(",")]
        return f"\\textsuperscript{{{compress(ns)}}}"
    s = replace_cmd(s, "cite", cite)
    def numcap(m):
        cap, lab = m.group(1), m.group(2)
        kind = "Fig." if lab.startswith("fig:") else "Table"
        return f"\\caption{{\\textbf{{{kind} {labels.get(lab, '??')} |}} {cap}}}\\label{{{lab}}}"
    s = re.sub(r"\\caption\{(.*?)\}\\label\{((?:fig|tab):[^}]*)\}", numcap, s)
    s = replace_cmd(s, "ref", lambda k: labels.get(k, "??"))
    s = replace_cmd(s, "TBD", lambda x: f"\\textbf{{[TBD: {x}]}}")
    s = replace_cmd(s, "bmhead", lambda x: f"\\section*{{{x}}}")
    s = s.replace("\\botrule", "\\bottomrule")
    s = s.replace("\\checkmark", "\u2713").replace("\\multicolumn{6}{@{}l}", "\\multicolumn{6}{l}")
    s = s.replace("$>$", ">").replace("$<$", "<").replace("$\\geq$", "\u2265").replace("$\\leq$", "\u2264")
    s = re.sub(r"\\makebox\[[^\]]*\]\[c\]\{(\\includegraphics\[[^\]]*\]\{[^}]*\})\}", r"\1", s)
    os.makedirs(os.path.join(TMP, "figs"), exist_ok=True)

    def small(m):
        from PIL import Image
        src = os.path.join(HERE, m.group(1) + ".png")
        dst = os.path.join(TMP, "figs", os.path.basename(m.group(1)) + ".png")
        im = Image.open(src)
        if im.mode != "RGB":
            bg = Image.new("RGB", im.size, "white")
            bg.paste(im, mask=im.split()[-1] if im.mode == "RGBA" else None)
            im = bg
        if im.width > 3000:  # ~400 dpi at 183 mm; keeps the .docx under the 30 MB upload limit
            im = im.resize((3000, round(im.height * 3000 / im.width)), Image.LANCZOS)
        im.save(dst, optimize=True)
        return "\\includegraphics[width=6.5in]{" + dst + "}"
    s = re.sub(r"\\includegraphics\[[^\]]*\]\{([^}]*)\.pdf\}", small, s)
    s = re.sub(r"\\(clearpage|newpage|medskip|footnotesize|small)\b", "", s)
    s = s.replace("\\par\\medskip", "\n\n").replace("$|$", "|")
    s = re.sub(r"\\setlength\\tabcolsep\{[^}]*\}", "", s)

    doc = ("\\documentclass{article}\n\\usepackage{graphicx,amsmath,amssymb,booktabs,multirow}\n"
           "\\begin{document}\n" + s + "\n\\end{document}\n")
    os.makedirs(TMP, exist_ok=True)
    tex = os.path.join(TMP, "word_src.tex")
    open(tex, "w", encoding="utf-8").write(doc)
    subprocess.run(["pandoc", tex, "-f", "latex", "-t", "docx", "-o", OUT, "--resource-path", HERE], check=True, cwd=HERE)
    widen_tables(OUT)
    print("wrote", OUT, "refs", len(keys), "labels", len(labels))


def widen_tables(path, total=9360):
    """Make every table span the text width (6.5 in): pandoc writes auto-width tables with
    narrow equal grid columns, which Word/LibreOffice render with wrapped numbers."""
    import shutil
    import zipfile
    tmp = path + ".tmp"
    with zipfile.ZipFile(path) as zin, zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as zout:
        for it in zin.infolist():
            data = zin.read(it.filename)
            if it.filename == "word/document.xml":
                x = data.decode("utf-8")
                x = x.replace('<w:tblW w:type="auto" w:w="0" />', '<w:tblW w:type="pct" w:w="5000" /><w:tblLayout w:type="autofit" />')

                def fit(m):
                    tbl = m.group(0)
                    rows = re.findall(r"<w:tr[ >].*?</w:tr>", tbl, flags=re.S)
                    ncol = len(re.findall(r"<w:gridCol ", tbl))
                    need = [7] * ncol
                    for r in rows:
                        cells = re.findall(r"<w:tc>.*?</w:tc>", r, flags=re.S)
                        if len(cells) != ncol:
                            continue  # spanning rows do not set widths
                        for k, c in enumerate(cells):
                            txt = "".join(re.findall(r"<(?:w|m):t[^>]*>([^<]*)<", c))
                            need[k] = max(need[k], min(len(txt), 24) + 3)
                    tot = sum(need)
                    w = [max(500, round(total * n / tot)) for n in need]
                    tbl = re.sub(r"<w:tblGrid>.*?</w:tblGrid>",
                                 "<w:tblGrid>" + "".join(f'<w:gridCol w:w="{c}" />' for c in w) + "</w:tblGrid>", tbl, flags=re.S)

                    def row(rm):
                        cells = re.findall(r"<w:tc>.*?</w:tc>", rm.group(0), flags=re.S)
                        if len(cells) != ncol:
                            return rm.group(0)
                        out = rm.group(0)
                        for k, c in enumerate(cells):
                            out = out.replace(c, c.replace("<w:tcPr />", f'<w:tcPr><w:tcW w:type="dxa" w:w="{w[k]}" /></w:tcPr>', 1), 1)
                        return out
                    return re.sub(r"<w:tr[ >].*?</w:tr>", row, tbl, flags=re.S)
                x = re.sub(r"<w:tbl>.*?</w:tbl>", fit, x, flags=re.S)
                data = x.encode("utf-8")
            zout.writestr(it, data)
    shutil.move(tmp, path)


if __name__ == "__main__":
    main()
